// Template weekly report when budget exhausted
const data = $('Get Weekly Data').item.json;
const revenue = data.total_revenue || 0;
const bookings = data.total_bookings || 0;
const avgStay = data.avg_stay_length || 0;

let message = `📊 *Weekly Performance Report*\n\n`;
message += `🏠 *${data.property_name}*\n\n`;
message += `*30-Day Metrics:*\n`;
message += `• Total Bookings: ${bookings}\n`;
message += `• Revenue: $${parseFloat(revenue).toFixed(2)}\n`;
message += `• Avg Stay: ${parseFloat(avgStay).toFixed(1)} nights\n`;
message += `• New This Week: ${data.new_bookings_week || 0}\n\n`;

if (bookings > 0) {
  message += `Keep up the great work! 🎉`;
} else {
  message += `Consider promotional activities to boost bookings.`;
}

return {
  property_id: data.property_id,
  text: message,
  channel: data.preferred_platform || 'telegram',
  recipient: data.owner_contact
};

